inline ::flatbuffers::Offset<AGR> CreateAGR(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    agrKind KIND = agrKind_Histogram,
    ::flatbuffers::Offset<::flatbuffers::String> SCHEMA_NAME = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SQL = 0,
    ::flatbuffers::Offset<::flatbuffers::String> X_FIELD = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> Y_FIELDS = 0,
    bool X_IS_TIME = false,
    ::flatbuffers::Offset<::flatbuffers::String> X_UNIT = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<AGRBin>>> BINS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<AGRCategory>>> CATEGORIES = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<AGRSeries>>> SERIES = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<AGRPivotCell>>> PIVOT = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> ROW_KEYS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> COL_KEYS = 0,
    uint64_t SCANNED = 0,
    uint64_t MATCHED = 0,
    uint64_t STORED = 0,
    bool PARTIAL = false,
    bool TRUNCATED = false,
    uint32_t ELAPSED_MS = 0,
    int64_t AS_OF_MS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PROVIDER_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SOURCE_NAME = 0) {
  AGRBuilder builder_(_fbb);
  builder_.add_AS_OF_MS(AS_OF_MS);
  builder_.add_STORED(STORED);
  builder_.add_MATCHED(MATCHED);
  builder_.add_SCANNED(SCANNED);
  builder_.add_SOURCE_NAME(SOURCE_NAME);
  builder_.add_PROVIDER_ID(PROVIDER_ID);
  builder_.add_ELAPSED_MS(ELAPSED_MS);
  builder_.add_COL_KEYS(COL_KEYS);
  builder_.add_ROW_KEYS(ROW_KEYS);
  builder_.add_PIVOT(PIVOT);
  builder_.add_SERIES(SERIES);
  builder_.add_CATEGORIES(CATEGORIES);
  builder_.add_BINS(BINS);
  builder_.add_X_UNIT(X_UNIT);
  builder_.add_Y_FIELDS(Y_FIELDS);
  builder_.add_X_FIELD(X_FIELD);
  builder_.add_SQL(SQL);
  builder_.add_SCHEMA_NAME(SCHEMA_NAME);
  builder_.add_TRUNCATED(TRUNCATED);
  builder_.add_PARTIAL(PARTIAL);
  builder_.add_X_IS_TIME(X_IS_TIME);
  builder_.add_KIND(KIND);
  return builder_.Finish();
}

