inline const AGR *GetAGR(const void *buf) {
  return ::flatbuffers::GetRoot<AGR>(buf);
}

inline const AGR *GetSizePrefixedAGR(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<AGR>(buf);
}

inline const char *AGRIdentifier() {
  return "$AGR";
}

inline bool AGRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, AGRIdentifier());
}

inline bool SizePrefixedAGRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, AGRIdentifier(), true);
}

template <bool B = false>
inline bool VerifyAGRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<AGR>(AGRIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedAGRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<AGR>(AGRIdentifier());
}

inline void FinishAGRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<AGR> root) {
  fbb.Finish(root, AGRIdentifier());
}

inline void FinishSizePrefixedAGRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<AGR> root) {
  fbb.FinishSizePrefixed(root, AGRIdentifier());
}

